"""Algorithm 1 — Greedy Budget-B Top-Set Selection.

Selects the B highest-scoring keys.  Its output is always a *top set*: a
budget-B set no member of which is scored below a non-member.  Every transfer
theorem in the theory applies verbatim to the output of this routine.
"""

from __future__ import annotations

import heapq
from typing import Iterable, List, Sequence, Tuple


def greedy_top_set(score: Sequence[float], budget: int) -> Tuple[int, ...]:
    """Return the indices of the `budget` highest-scoring keys, sorted.

    Complexity: O(n log B) time with a size-B min-heap, O(B) extra space.
    Ties are broken by index, which is one admissible choice among possibly
    many; every choice yields a top set.
    """
    n = len(score)
    if not 0 <= budget <= n:
        raise ValueError(f"budget {budget} out of range for {n} keys")
    if budget == 0:
        return ()
    heap: List[Tuple[float, int]] = []
    for i, s in enumerate(score):
        if len(heap) < budget:
            heapq.heappush(heap, (s, -i))
        elif (s, -i) > heap[0]:
            heapq.heapreplace(heap, (s, -i))
    return tuple(sorted(-j for _, j in heap))


def is_top_set(score: Sequence[float], budget: int,
               selection: Iterable[int], tol: float = 1e-12) -> bool:
    """Verify the defining property of a top set.  Complexity O(n·B)."""
    sel = set(selection)
    if len(sel) != budget:
        return False
    outside = [j for j in range(len(score)) if j not in sel]
    return all(score[j] <= score[i] + tol for i in sel for j in outside)


def retained_mass(importance: Sequence[float], selection: Iterable[int]) -> float:
    """Attention mass preserved by a selection."""
    return float(sum(importance[i] for i in selection))


def oracle_gap(importance: Sequence[float], score: Sequence[float],
               budget: int) -> float:
    """Retention deficit of `score` against the oracle at the given budget.

    By the oracle bound this is always non-negative, and by the transfer
    theorems it is at most 2·B·eps (L-infinity) and 2·sqrt(B·SSE) (L-2).
    """
    chosen = greedy_top_set(score, budget)
    best = greedy_top_set(importance, budget)
    return retained_mass(importance, best) - retained_mass(importance, chosen)
